(function(){
 'use strict';const $=id=>document.getElementById(id),{n,download,sourceBox}=PlatformUI,M=LearningModel,D=window.WORKSHOP_CONTENT,bank=window.KNOWLEDGE_BANK;
 let storage;try{storage=localStorage;}catch{}const store=new M.Store(storage);let unsaved=false;
 const status=t=>$('learningStatus').textContent=t;
 function notice(){const e=$('learningStorage');e.hidden=!store.notice;e.textContent=store.notice;}
 function action(text,fn,cls='quiet outlined'){const b=n('button',text,cls);b.type='button';b.onclick=fn;return b;}
 function a(text,href){const e=n('a',text);e.href=href;return e;}
 function update(id,fields,expected){try{const next=store.update(id,fields,expected);unsaved=!store.writable;notice();return next;}catch(e){unsaved=true;status(e.message);return null;}}
 function field(label,value,change,{short=false,placeholder='',disabled=false}={}){const l=n('label',label,'learning-field'),t=n(short?'input':'textarea');if(short)t.type='text';t.value=value||'';t.maxLength=10000;t.placeholder=placeholder;t.disabled=disabled;t.oninput=()=>change(t.value);l.append(t);return{label:l,input:t};}
 function picker(items,id,tab,label='Упражнение'){const l=n('label',label,'learning-picker'),s=n('select');for(const i of items){const o=n('option',i.title);o.value=i.id;s.append(o);}s.value=id;s.onchange=()=>{location.hash=tab+'&item='+s.value;};l.append(s);return l;}
 function rubric(item,key,r){const f=n('fieldset',undefined,'learning-rubric');f.append(n('legend','Самопроверка по открытым критериям'));for(const [i,text]of item.rubric.entries()){const l=n('label'),c=n('input');c.type='checkbox';c.value=String(i);c.checked=(r.checks||[]).includes(String(i));c.onchange=()=>{const next=update(key,{checks:[...f.querySelectorAll('input:checked')].map(x=>x.value)},r);if(next)r=next;};l.append(c,document.createTextNode(text));f.append(l);}return f;}
 function sourceLink(source){const href=M.sourceHref(source);return href?a(source.title||'Открыть исходный раздел',href):n('span','Личная карточка без ссылки на учебник','learning-small');}
 function home(panel){
  const cards=store.list('card'),due=cards.filter(c=>c.dueAt<=Date.now()).length,grid=n('div',undefined,'platform-grid');
  const cardWord=cards.length%10===1&&cards.length%100!==11?'карточка':cards.length%10>=2&&cards.length%10<=4&&(cards.length%100<12||cards.length%100>14)?'карточки':'карточек';
  const entries=[['Опиши симптом без диагноза',D.describe.length+' ситуаций: наблюдение, переживание и интерпретация.','#describe'],['Составь психический статус',D.status.length+' сценария; образцы по областям и обозначение неизвестного.','#status'],['Проверь понятие на новой ситуации',D.concepts.reduce((s,c)=>s+c.cases.length,0)+' вариантов по '+D.concepts.length+' темам.','#transfer'],['Карточки из своих заметок',cards.length+' '+cardWord+' · '+due+' пора повторить.','#cards'],['Личный журнал заблуждений','Запишите основание ошибки и признак, который изменит решение.','#journal'],['Критическое чтение исследований',D.research.length+' вымышленных исследования: эффекты, скрининг, смешение.','#research'],['Предскажи → проверь → объясни','Сохраняемый эксперимент в каждой из 13 моделей.','neuro.html#neuron'],['Облегчённые модели','13 интерактивных 2D-схем без WebGL и тяжёлых сеток.','neuro.html?view=2d#neuron']];
  for(const [title,text,href]of entries){const card=n('article',undefined,'platform-card');card.append(n('h2',title),n('p',text),a('Открыть →',href));grid.append(card);}panel.append(grid);
 }
 function freeResponse(panel,tab,item,group){
  const key='learn-response-'+tab+'-'+item.id;let r=store.get(key)||{kind:'response',draft:'',unlocked:false,checks:[]};
  panel.append(picker(group,item.id,tab),n('h2',item.title),n('p',item.story,'platform-note'));
  if(item.table){const wrap=n('div',undefined,'platform-timeline');wrap.tabIndex=0;wrap.setAttribute('role','region');wrap.setAttribute('aria-label','Данные вымышленного исследования');const table=n('table',undefined,'learning-data');for(const [i,row]of item.table.entries()){const tr=n('tr');for(const x of row){const cell=n(i?'td':'th',x);if(!i)cell.scope='col';tr.append(cell);}table.append(tr);}wrap.append(table);panel.append(wrap);}
  if(item.prompt)panel.append(n('p',item.prompt));
  const form=n('div',undefined,'learning-form');
  if(tab==='status'){
   panel.append(n('p','Заполняйте только то, что дано. Для остальных областей укажите «нет данных» или «не исследовано».','learning-small'));
   for(const [id,title]of item.fields){const f=field(title,r['field-'+id],value=>{const next=update(key,{kind:'response',['field-'+id]:value},r);if(next)r=next;});f.input.dataset.area=id;form.append(f.label);}
  }else form.append(field(tab==='describe'?'Ваше описание и следующий уточняющий вопрос':'Ваш разбор и вычисления',r.draft,value=>{const next=update(key,{kind:'response',draft:value},r);if(next)r=next;},{placeholder:'Сначала сформулируйте своими словами.'}).label);
  form.append(action('Открыть образец и критерии',()=>{const texts=tab==='status'?item.fields.map(([id])=>r['field-'+id]||''):[r.draft||''];if(texts.join(' ').trim().length<20){status('Запишите свой ответ — минимум 20 символов — перед открытием образца. Длина не является оценкой качества.');return;}const next=update(key,{kind:'response',unlocked:true},r);if(next){render();status('Образец открыт. Отметки по критериям — ваша самопроверка, а не экспертная оценка.');}},'primary'));panel.append(form);
  if(r.unlocked){const box=n('section',undefined,'learning-example');box.append(n('h3','Возможный вариант описания'));if(tab==='status'){for(const [id,title,example]of item.fields)box.append(n('h4',title),n('p',example));}else box.append(n('p',item.example));if(item.next)box.append(n('p','Что уточнить: '+item.next));panel.append(box,rubric(item,key,r),sourceBox(item.sources));if(item.lab)panel.append(a('Проверить численную модель →',item.lab));}
 }
 function transfer(panel,params){
  const concept=D.concepts.find(c=>c.id===(params.get('concept')||params.get('item')))||D.concepts[0];
  const keyFor=v=>'learn-variant-'+v.id;
  const v=concept.cases.find(v=>v.id===params.get('variant'))||M.nextVariant(concept.cases,store.state.cases)||concept.cases[0];
  if(params.get('variant')!==v.id)history.replaceState(null,'','#transfer&concept='+concept.id+'&variant='+v.id);
  let r=store.get(keyFor(v))||{kind:'variant',choice:'',reason:'',locked:false};
  const choose=picker(D.concepts,concept.id,'transfer','Понятие');panel.append(choose,n('h2',concept.title),n('p','Ситуация '+(concept.cases.indexOf(v)+1)+' из '+concept.cases.length+'. Это отдельная учебная проверка; ответы основного теста не меняются.','learning-small'),n('p',v.stem,'platform-note'));
  const f=n('fieldset',undefined,'platform-card');f.append(n('legend','Какое описание точнее соответствует данным?'));
  const offset=(concept.cases.indexOf(v)+D.concepts.indexOf(concept))%concept.options.length;
  for(let j=0;j<concept.options.length;j++){const i=(j+offset)%concept.options.length,l=n('label',undefined,'learning-choice'),input=n('input');input.type='radio';input.name='transfer-choice';input.value=String(i);input.checked=r.choice===String(i);input.disabled=r.locked;input.onchange=()=>{const next=update(keyFor(v),{kind:'variant',choice:String(i)},r);if(next)r=next;};l.append(input,document.createTextNode(concept.options[i]));f.append(l);}panel.append(f);
  const reason=field('Какой признак определил ваш выбор?',r.reason,value=>{const next=update(keyFor(v),{kind:'variant',reason:value},r);if(next)r=next;},{disabled:r.locked});panel.append(reason.label);
  if(!r.locked)panel.append(action('Зафиксировать ответ и открыть разбор',()=>{if(r.choice===''||(r.reason||'').trim().length<10){status('Выберите вариант и назовите признак своими словами.');return;}if(update(keyFor(v),{kind:'variant',locked:true,correct:Number(r.choice)===v.correct,concept:concept.id},r)){render();}},'primary'));
  else{const box=n('section',undefined,'learning-result'+(r.correct?'':' learning-error'));box.append(n('strong',r.correct?'Выбран ожидаемый вариант.':'Сопоставьте выбранный вариант с данными.'),n('p','Ожидаемый ответ: '+concept.options[v.correct]),n('p',v.why),n('p','Ваше обоснование не оценивается алгоритмом.','learning-small'));panel.append(box,sourceBox(concept.sources));if(!r.correct)panel.append(a('Записать, что привело к ошибке →','workshop.html#journal&variant='+v.id));const next=M.nextVariant(concept.cases,store.state.cases,v.id);if(next)panel.append(a('Другая ситуация на это понятие →','#transfer&concept='+concept.id+'&variant='+next.id));}
 }
 function cards(panel){
  panel.append(n('h2','Карточки из личных заметок'));const create=n('details',undefined,'platform-details');create.append(n('summary','Создать карточку'));const form=n('form',undefined,'learning-form');const question=field('Вопрос','',()=>{},{short:true}),answer=field('Ответ','',()=>{});form.append(question.label,answer.label);const submit=n('button','Сохранить карточку','primary');submit.type='submit';form.append(submit);form.onsubmit=e=>{e.preventDefault();if(!question.input.value.trim()||!answer.input.value.trim()){status('Заполните вопрос и ответ.');return;}const id=M.newId('card');if(update(id,{kind:'card',question:question.input.value.trim(),answer:answer.input.value.trim(),stage:0,dueAt:Date.now(),reviews:0})){render();status('Карточка создана. Из текста учебника и конспекта можно создавать карточки со ссылкой на источник.');}};create.append(form);panel.append(create);
  const all=store.list('card').sort((a,b)=>a.dueAt-b.dueAt),due=all.filter(c=>c.dueAt<=Date.now());panel.append(n('p','Всего: '+all.length+' · к повторению: '+due.length+'. Сначала вспомните ответ, затем откройте его.','learning-small'));
  if(!all.length){panel.append(n('p','Создайте карточку здесь или нажмите «Карточка» в читателе / «В карточку» в конспекте.','learning-empty'));return;}
  const upcoming=n('details',undefined,'platform-details');upcoming.append(n('summary','Показать карточки, срок которых ещё не наступил'));
  for(const card of all){let r=store.get(card.id),box=n('article',undefined,'platform-card'),reveal=n('div',undefined,'learning-answer'),actions=n('div',undefined,'learning-card-actions');box.append(n('h3',card.question),n('p','Повторить: '+new Date(card.dueAt).toLocaleString('ru-RU'),'learning-small'));reveal.hidden=true;reveal.append(n('p',card.answer),sourceLink(card.source));const controls=n('div',undefined,'learning-card-actions');for(const [rating,title]of [['again','Не вспомнил · 10 мин'],['hard','С трудом · 1 день'],['good','Вспомнил']])controls.append(action(title,()=>{const next=M.reviewCard(r,rating);if(update(card.id,next,r)){render();status('Следующее повторение: '+new Date(next.dueAt).toLocaleString('ru-RU'));}}));reveal.append(controls);actions.append(action('Показать ответ',e=>{reveal.hidden=false;actions.querySelector('button').disabled=true;},'primary'),action('Изменить',()=>editCard(card)),action('Удалить',()=>remove(card.id,'Карточка удалена.')));box.append(actions,reveal);(card.dueAt<=Date.now()?panel:upcoming).append(box);}if(all.length>due.length)panel.append(upcoming);
 }
 function remove(id,text){const old=store.get(id);if(update(id,{deleted:true},old)){render();status(text);$('learningStatus').append(document.createTextNode(' '),action('Отменить',()=>{try{store.update(id,{deleted:false},null,true);render();status('Запись восстановлена.');}catch(e){status(e.message);}}));}}
 function editCard(card){const dialog=n('dialog',undefined,'learning-dialog'),title=n('h2','Изменить карточку'),form=n('form',undefined,'learning-form');title.id='editCardTitle';dialog.setAttribute('aria-labelledby',title.id);let r=store.get(card.id);const q=field('Вопрос',r.question,()=>{},{short:true}),ans=field('Ответ',r.answer,()=>{});form.append(q.label,ans.label);const save=n('button','Сохранить','primary');save.type='submit';const error=n('p',undefined,'platform-error');error.hidden=true;error.setAttribute('role','alert');form.append(save,action('Отмена',()=>dialog.close()),error);form.onsubmit=e=>{e.preventDefault();if(!q.input.value.trim()||!ans.input.value.trim()){status('Заполните вопрос и ответ.');return;}if(update(card.id,{question:q.input.value.trim(),answer:ans.input.value.trim()},r)){dialog.close();render();}else{error.hidden=false;error.textContent=$('learningStatus').textContent;}};dialog.append(title,form);dialog.onclose=()=>dialog.remove();document.body.append(dialog);dialog.showModal();}
 function journal(panel,params){
  panel.append(n('h2','Мой журнал заблуждений'));const q=bank.questions.find(q=>q.id===params.get('question')),variant=D.concepts.flatMap(c=>c.cases).find(v=>v.id===params.get('variant'));
  let key=q?'learn-journal-question-'+q.id:variant?'learn-journal-variant-'+variant.id:params.get('entry')||M.newId('journal');if(store.get(key)?.deleted)key=M.newId('journal');let r=store.get(key)||{kind:'journal',situation:q?.stem||variant?.stem||'',belief:'',evidence:'',change:'',reflection:''};
  if(!/^learn-journal-[a-z0-9-]+$/.test(key)){status('Неверная ссылка на запись.');return;}
  if(q)panel.append(n('p','Из задания: '+q.topic,'learning-small'));const form=n('div',undefined,'learning-form');
  for(const [id,title]of [['situation','Ситуация или вопрос'],['belief','Что я предполагал и почему выбрал этот ответ?'],['evidence','Какой признак я пропустил или истолковал неверно?'],['change','Какие новые сведения изменят мой выбор?'],['reflection','Что я проверю в следующий раз?']])form.append(field(title,r[id],value=>{const next=update(key,{kind:'journal',[id]:value},r);if(next)r=next;}).label);
  form.append(action('Сохранить и вернуться к журналу',()=>{if(!(r.belief||'').trim()||!(r.change||'').trim()){status('Запишите основание своего выбора и сведения, которые могут его изменить.');return;}let source=r.source;if(q)source={book:q.book,sectionId:q.sectionId,block:bank.sourceLocations?.[q.id]||0,title:q.topic};if(variant){const ref=D.concepts.find(c=>c.cases.some(v=>v.id===variant.id))?.sources[0];if(ref)source={book:ref.bookKey,sectionId:ref.sectionId,block:ref.block,title:ref.title};}if(update(key,{kind:'journal',source:source||null,reviewedAt:Date.now()},r)){location.hash='journal';render();status('Запись сохранена. Вернитесь к ней после новой ситуации.');}},'primary'));panel.append(form);
  if(q)panel.append(sourceLink({book:q.book,sectionId:q.sectionId,block:bank.sourceLocations?.[q.id]||0,title:'Свериться с исходным разделом'}));
  const entries=store.list('journal').sort((a,b)=>b.updatedAt-a.updatedAt);panel.append(n('h3','Сохранённые записи · '+entries.length));for(const entry of entries){const box=n('article',undefined,'learning-review-item');box.append(n('p',entry.situation||'Личная учебная запись'),n('p',entry.belief||'Черновик','learning-small'),a('Открыть запись →','#journal&entry='+entry.id),action('Удалить',()=>remove(entry.id,'Запись удалена.')));panel.append(box);}
 }
 function render(){
  const [tab='home',...rest]=location.hash.slice(1).split('&'),params=new URLSearchParams(rest.join('&')),panel=$('learningPanel');panel.replaceChildren();status('');notice();for(const link of document.querySelectorAll('.platform-tabs a')){if(link.hash==='#'+tab)link.setAttribute('aria-current','page');else link.removeAttribute('aria-current');}
  if(!D){status('Материалы мастерской не загрузились. Обновите страницу.');return;}
  if(tab==='home')home(panel);else if(['describe','status','research'].includes(tab)){const group=D[tab],item=group.find(i=>i.id===params.get('item'))||group[0];freeResponse(panel,tab,item,group);}else if(tab==='transfer')transfer(panel,params);else if(tab==='cards')cards(panel);else if(tab==='journal')journal(panel,params);else location.hash='home';
 }
 $('exportLearning').onclick=()=>{download('psycholibrary-practice-backup.json',{format:'psycholibrary-practice-backup',schemaVersion:1,state:store.state,unsavedDrafts:unsaved?[...document.querySelectorAll('#learningPanel textarea,#learningPanel input[type=text]')].map(t=>({label:t.parentElement.textContent,value:t.value})):[]});status('Копия подготовлена. Для переноса используйте «Общую резервную копию» → «Восстановить из файла».');};
 window.addEventListener('hashchange',render);window.addEventListener('beforeunload',e=>{if(unsaved){e.preventDefault();e.returnValue='';}});window.addEventListener('storage',e=>{if(e.key===PlatformModel.PRACTICE)status('Практика изменена в другой вкладке. Независимые записи сохраняются; перед редактированием этой же записи обновите страницу.');});render();
})();
